class RobotPet:
    """A small robot pet whose battery level is always between 0 and 100."""

    def __init__(self, name):
        self.name = name
        self.battery = 100

    def charge(self, amount):
        new_level = self.battery + amount
        if new_level > 100:
            new_level = 100
        if new_level < 0:
            new_level = 0
        self.battery = new_level
